{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'fs';

// Read all input from stdin
const input = readFileSync(0, 'utf-8');

// Parse command line
const mode = process.argv[2];
if (!mode || !['rounds', 'tally'].includes(mode)) {
  process.stderr.write('error: usage: cli.js rounds|tally\n');
  process.exit(2);
}

// Parse input
const lines = input.split('\n');
// Drop the empty tail a trailing newline leaves
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop();
}

// Process lines
let lineNum = 0;
let candidates = null;
let ballots = [];
let candidatesDeclared = false;

for (const rawLine of lines) {
  lineNum++;

  // Trim line
  let line = rawLine.trim();

  // Ignore empty lines and comments
  if (line === '' || line.startsWith('#')) {
    continue;
  }

  // Split on runs of whitespace
  const tokens = line.split(/\s+/);

  if (tokens[0] === 'candidates') {
    // Check if already declared
    if (candidatesDeclared) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
      process.exit(2);
    }

    if (tokens.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected candidates <name>...\n`);
      process.exit(2);
    }

    const names = tokens.slice(1);
    // Validate names - must be one or more of A-Z, a-z, 0-9, _, -
    const validName = /^[A-Za-z0-9_-]+$/;
    for (const name of names) {
      if (!validName.test(name)) {
        process.stderr.write(`error: line ${lineNum}: invalid candidate name ${name}\n`);
        process.exit(2);
      }
    }

    // Check for duplicates
    const seen = new Set();
    for (const name of names) {
      if (seen.has(name)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${name} is declared twice\n`);
        process.exit(2);
      }
      seen.add(name);
    }

    candidates = names;
    candidatesDeclared = true;
  } else if (tokens[0] === 'ballot') {
    // Check if candidates declared
    if (!candidatesDeclared) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
      process.exit(2);
    }

    if (tokens.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`);
      process.exit(2);
    }

    // Parse count - decimal integer without sign or leading zero
    const countStr = tokens[1];
    let count;
    if (!/^\d+$/.test(countStr)) {
      process.stderr.write(`error: line ${lineNum}: count must be a positive integer\n`);
      process.exit(2);
    }
    count = parseInt(countStr, 10);
    if (count < 1 || countStr !== String(count)) {
      process.stderr.write(`error: line ${lineNum}: count must be a positive integer\n`);
      process.exit(2);
    }

    if (tokens.length < 3) {
      process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`);
      process.exit(2);
    }

    const chosenCandidates = tokens.slice(2);

    // Validate candidates exist
    for (const name of chosenCandidates) {
      if (!candidates.includes(name)) {
        process.stderr.write(`error: line ${lineNum}: unknown candidate ${name}\n`);
        process.exit(2);
      }
    }

    // Check for duplicates in ballot
    const seenInBallot = new Set();
    for (const name of chosenCandidates) {
      if (seenInBallot.has(name)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${name} is repeated\n`);
        process.exit(2);
      }
      seenInBallot.add(name);
    }

    // Add this ballot count times
    for (let i = 0; i < count; i++) {
      ballots.push(chosenCandidates);
    }
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${tokens[0]}\n`);
    process.exit(2);
  }
}

// Check if candidates were declared
if (!candidatesDeclared) {
  process.stderr.write('error: no candidates\n');
  process.exit(2);
}

// Now simulate the election
let continuing = new Set(candidates);
const rounds = [];
let winner = null;

while (true) {
  // Count votes in this round
  const votes = {};
  let active = 0;

  // Initialize all continuing candidates with 0 votes
  for (const candidate of continuing) {
    votes[candidate] = 0;
  }

  // Count ballots
  for (const ballot of ballots) {
    // Find first continuing candidate on this ballot
    for (const candidate of ballot) {
      if (continuing.has(candidate)) {
        votes[candidate]++;
        active++;
        break;
      }
    }
  }

  // Record round
  const round = { 
    votes: { ...votes }, 
    active,
    continuing: new Set(continuing)
  };
  rounds.push(round);

  // Check for winner or end condition
  if (active === 0) {
    // No ballots counted - election ends with no winner
    break;
  }

  let winnerCandidate = null;
  for (const candidate of continuing) {
    if (votes[candidate] * 2 > active) {
      winnerCandidate = candidate;
      break;
    }
  }

  if (winnerCandidate) {
    winner = winnerCandidate;
    break;
  }

  // Eliminate candidate with fewest votes
  let minVotes = Infinity;
  const candidatesWithMin = [];

  for (const candidate of continuing) {
    if (votes[candidate] < minVotes) {
      minVotes = votes[candidate];
      candidatesWithMin.length = 0;
      candidatesWithMin.push(candidate);
    } else if (votes[candidate] === minVotes) {
      candidatesWithMin.push(candidate);
    }
  }

  let toEliminate = candidatesWithMin[0];

  if (candidatesWithMin.length > 1) {
    // Tie-break by comparing across rounds
    let tied = candidatesWithMin;

    for (let roundIdx = 0; roundIdx < rounds.length; roundIdx++) {
      let minInRound = Infinity;
      for (const candidate of tied) {
        const votesInRound = rounds[roundIdx].votes[candidate] || 0;
        minInRound = Math.min(minInRound, votesInRound);
      }

      const beforeLen = tied.length;
      tied = tied.filter(c => (rounds[roundIdx].votes[c] || 0) === minInRound);

      if (tied.length === 1) {
        toEliminate = tied[0];
        break;
      }
    }

    if (tied.length > 1) {
      // Still tied - eliminate by reverse alphabetical order (sorts last by code point)
      toEliminate = tied.sort().reverse()[0];
    }
  }

  round.eliminated = toEliminate;
  continuing.delete(toEliminate);
}

// Output
if (mode === 'rounds') {
  for (let i = 0; i < rounds.length; i++) {
    const round = rounds[i];

    // Sort continuing candidates by descending votes, then by name
    const sortedCandidates = Array.from(round.continuing).sort((a, b) => {
      const votesA = round.votes[a];
      const votesB = round.votes[b];
      if (votesA !== votesB) {
        return votesB - votesA;  // descending
      }
      return a.localeCompare(b);  // ascending by name
    });

    const counts = sortedCandidates.map(c => `${c}=${round.votes[c]}`).join(' ');
    const exhausted = ballots.length - round.active;
    process.stdout.write(`round ${i + 1}: ${counts} exhausted=${exhausted}\n`);

    if (round.eliminated) {
      process.stdout.write(`eliminated ${round.eliminated}\n`);
    }
  }
} else if (mode === 'tally') {
  process.stdout.write(`rounds ${rounds.length}\n`);
}

if (winner) {
  process.stdout.write(`winner ${winner}\n`);
} else {
  process.stdout.write('no winner\n');
}

process.exit(0);
"}

