    let tied = candidatesWithMin;

    for (let roundIdx = 0; roundIdx < rounds.length; roundIdx++) {
      let minInRound = Infinity;
      for (const candidate of tied) {
        const votesInRound = rounds[roundIdx].votes[candidate] || 0;
        minInRound = Math.min(minInRound, votesInRound);
