    const round = rounds[i];

    // Sort continuing candidates by descending votes, then by name
    const sortedCandidates = Array.from(round.continuing).sort((a, b) => {
      const votesA = round.votes[a];
      const votesB = round.votes[b];
      if (votesA !== votesB) {
