{"file_path":"src/count.js","content":"/** The instant-runoff count itself. */

function byCodePoint(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/** Pick the candidate to eliminate among those tied for fewest votes. */
function pickEliminated(tiedInput, history) {
  let tied = tiedInput.slice()
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    const votes = history[r]
    let least = Infinity
    for (const name of tied) {
      const v = votes.get(name) ?? 0
      if (v < least) least = v
    }
    tied = tied.filter((name) => (votes.get(name) ?? 0) === least)
  }
  if (tied.length === 1) return tied[0]
  return tied.sort(byCodePoint)[tied.length - 1]
}

export function count({ candidates, ballots }) {
  const total = ballots.reduce((sum, b) => sum + b.weight, 0)
  const continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) votes.set(name, 0)
    }
    let active = 0
    for (const ballot of ballots) {
      for (const name of ballot.prefs) {
        if (continuing.has(name)) {
          votes.set(name, votes.get(name) + ballot.weight)
          active += ballot.weight
          break
        }
      }
    }

    const round = {
      votes,
      exhausted: total - active,
      standing: Array.from(continuing),
      eliminated: null,
    }
    rounds.push(round)
    history.push(votes)

    if (active === 0) break

    let majority = null
    for (const [name, v] of votes) {
      if (v * 2 > active) {
        majority = name
        break
      }
    }
    if (majority !== null) {
      winner = majority
      break
    }

    let least = Infinity
    for (const v of votes.values()) if (v < least) least = v
    const tied = []
    for (const [name, v] of votes) if (v === least) tied.push(name)

    const out = tied.length === 1 ? tied[0] : pickEliminated(tied, history)
    round.eliminated = out
    continuing.delete(out)
  }

  return { rounds, winner }
}
"}

