{"file_path":"src/render.js","content":"/** Formatting of the count for both output modes. */

export function render(mode, { rounds, winner }) {
  const parts = []
  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i]
      const names = round.standing.slice().sort((a, b) => {
        const va = round.votes.get(a)
        const vb = round.votes.get(b)
        if (va !== vb) return vb - va
        return a < b ? -1 : a > b ? 1 : 0
      })
      const cells = names.map((name) => `${name}=${round.votes.get(name)}`)
      cells.push(`exhausted=${round.exhausted}`)
      parts.push(`round ${i + 1}: ${cells.join(' ')}\n`)
      if (round.eliminated !== null) parts.push(`eliminated ${round.eliminated}\n`)
    }
  } else {
    parts.push(`rounds ${rounds.length}\n`)
  }
  parts.push(winner === null ? 'no winner\n' : `winner ${winner}\n`)
  return parts.join('')
}
